for v in [175,180,185,190,195,200,205,210,215,220,225]:
 vals=d[v,320:341];print(v,[(round(float(x),3)) for x in vals[::5]])
 for u in [322,330,338]:
  z=float(d[v,u]);c=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);w=np.linalg.inv(np.vstack([E,[0,0,0,1]]))@c;print(' ',u,round(z,3),np.round(w[:3],3))
